import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Web UI, UX and accessibility audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/WEB-UI-UX-ACCESSIBILITY.html"}],["meta",{"property":"og:title","content":"Web UI, UX and accessibility audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/WEB-UI-UX-ACCESSIBILITY.html"}],["meta",{"name":"twitter:title","content":"Web UI, UX and accessibility audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/WEB-UI-UX-ACCESSIBILITY.md","filePath":"audits/WEB-UI-UX-ACCESSIBILITY.md","lastUpdated":1794184492000}`),a={name:`audits/WEB-UI-UX-ACCESSIBILITY.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="web-ui-ux-and-accessibility-audit" tabindex="-1">Web UI, UX and accessibility audit <a class="header-anchor" href="#web-ui-ux-and-accessibility-audit" aria-label="Permalink to “Web UI, UX and accessibility audit”">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Reviewed the browser form structure, account and cash-flow editors, strategy controls, status/error feedback, responsive CSS, motion helpers, focus/error handling, and the web rules in RULESETS.</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to “Findings”">​</a></h2><h3 id="ui-01-—-programmatic-smooth-scrolling-does-not-respect-reduced-motion-preference" tabindex="-1">UI-01 — Programmatic smooth scrolling does not respect reduced-motion preference <a class="header-anchor" href="#ui-01-—-programmatic-smooth-scrolling-does-not-respect-reduced-motion-preference" aria-label="Permalink to “UI-01 — Programmatic smooth scrolling does not respect reduced-motion preference”">​</a></h3><p><strong>Severity: P3</strong></p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L35" target="_blank" rel="noreferrer">app.js L35</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L51" target="_blank" rel="noreferrer">app.js L51</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L124" target="_blank" rel="noreferrer">app.js L124</a>.</p><p>Validation errors and the result section call <code>scrollIntoView({ behavior: &quot;smooth&quot; })</code> directly. The CSS and motion helpers support reduced motion, but these JavaScript calls do not check <code>prefers-reduced-motion</code>.</p><p><strong>Impact:</strong> users who request reduced motion can still receive smooth programmatic scrolling during validation or result display.</p><p><strong>Recommendation:</strong> centralize scrolling in a helper that uses <code>matchMedia(&quot;(prefers-reduced-motion: reduce)&quot;)</code> and chooses <code>behavior: &quot;auto&quot;</code> when reduced motion is enabled. Add a test for both branches.</p><h3 id="ui-02-—-help-tooltip-content-is-not-exposed-as-a-reliable-accessible-description" tabindex="-1">UI-02 — Help tooltip content is not exposed as a reliable accessible description <a class="header-anchor" href="#ui-02-—-help-tooltip-content-is-not-exposed-as-a-reliable-accessible-description" aria-label="Permalink to “UI-02 — Help tooltip content is not exposed as a reliable accessible description”">​</a></h3><p><strong>Severity: P3</strong></p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L67" target="_blank" rel="noreferrer">app.js L67</a> renders the outflow help marker as a focusable <code>span</code> with <code>role=&quot;img&quot;</code>, an aria-label of “Outflow payment policy help”, and tooltip text in a CSS <code>data-tooltip</code> pseudo-element.</p><p><strong>Impact:</strong> the actual Strict/Defer/Best effort explanation is not programmatically associated with the payment-policy control. A screen reader may announce only a generic “help” image, not the tooltip content.</p><p><strong>Recommendation:</strong> use a real button or a labelled help control with an adjacent element carrying an ID and <code>role=&quot;tooltip&quot;</code>; connect it with <code>aria-describedby</code>. Ensure the explanation can be opened and dismissed with keyboard and touch, not hover alone.</p><h3 id="ui-03-—-inline-validation-messages-are-not-explicitly-associated-with-their-fields" tabindex="-1">UI-03 — Inline validation messages are not explicitly associated with their fields <a class="header-anchor" href="#ui-03-—-inline-validation-messages-are-not-explicitly-associated-with-their-fields" aria-label="Permalink to “UI-03 — Inline validation messages are not explicitly associated with their fields”">​</a></h3><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L34-L35" target="_blank" rel="noreferrer">app.js L34-L35</a> adds <code>aria-invalid</code> and appends a visual <code>small.field-error</code>, but does not assign the message an ID or add that ID to the field&#39;s <code>aria-describedby</code>.</p><p><strong>Impact:</strong> focus moves to the invalid field, but assistive technology is not guaranteed to announce the corresponding error message.</p><p><strong>Recommendation:</strong> generate a stable error ID, set <code>aria-describedby</code> while the error is present, and restore the prior description when clearing errors. Keep the visible error and <code>aria-invalid</code> state.</p><h2 id="visual-and-interaction-assessment" tabindex="-1">Visual and interaction assessment <a class="header-anchor" href="#visual-and-interaction-assessment" aria-label="Permalink to “Visual and interaction assessment”">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to “Positive”">​</a></h3><ul><li>The form uses semantic labels, real buttons/links, headings and a clear primary action.</li><li>The account editor uses a radio control for the consolidation account and visually marks the selected card.</li><li>Specific cash-flow dates use a bounded date input with removable date chips.</li><li>The layout has desktop/tablet/mobile breakpoints, collapses the navigation rail on smaller screens, and uses larger mobile control sizes.</li><li>Focus-visible styling, touch-target sizing and reduced-motion CSS are present.</li><li>The recent visual-restraint pass reduced redundant numbering, decorative labels, heavy gradients and excessive pill/container treatments while preserving meaningful financial warnings and states.</li><li>Simulation status is exposed with a live status region and elapsed time.</li></ul><h3 id="gaps-requiring-rendered-qa" tabindex="-1">Gaps requiring rendered QA <a class="header-anchor" href="#gaps-requiring-rendered-qa" aria-label="Permalink to “Gaps requiring rendered QA”">​</a></h3><ul><li>No browser screenshot comparison or automated visual-regression suite was found in the repository tests.</li><li>Contrast has not been measured against WCAG 2.2 AA thresholds; token usage alone does not prove contrast.</li><li>Screen-reader announcement order, keyboard-only operation, browser zoom at 200–400%, and small viewport overflow were not manually verified.</li><li>The help tooltip and validation associations above need correction before calling accessibility QA complete.</li><li>Desktop/mobile layout and all meaningful states should be checked in the new dev preview once deployment succeeds.</li></ul><h2 id="required-manual-state-matrix" tabindex="-1">Required manual state matrix <a class="header-anchor" href="#required-manual-state-matrix" aria-label="Permalink to “Required manual state matrix”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>States to inspect</th></tr></thead><tbody><tr><td>Catalogue</td><td>loading, loaded, empty/unavailable, one bank with no rate data</td></tr><tr><td>Accounts</td><td>one account, many accounts, primary change, remove last account, imported unusual IDs</td></tr><tr><td>Cash flows</td><td>recurring/scheduled, long names, invalid date, outside-period date, strict/defer/best-effort</td></tr><tr><td>Strategy</td><td>Greedy, GSS, Absolute R+, setting panel transitions, decision cap reached</td></tr><tr><td>Simulation</td><td>preparing, running, edit while running, success, failure, reuse, superseded/cancelled</td></tr><tr><td>Results</td><td>no bookings, many bookings, outstanding outflows, large numbers, long labels</td></tr><tr><td>Motion</td><td>normal, reduced motion, keyboard, touch, interrupted transitions</td></tr><tr><td>Viewports</td><td>320px, 375px, 620px, 850px, 1280px and browser zoom</td></tr></tbody></table><h2 id="design-system-assessment" tabindex="-1">Design-system assessment <a class="header-anchor" href="#design-system-assessment" aria-label="Permalink to “Design-system assessment”">​</a></h2><p>The web UI has a coherent dark token-based palette and a restrained component language after the recent visual pass. Avoid another broad visual redesign. The next UI pass should prioritize functional clarity, error association, real-device inspection and contrast measurement rather than additional styling.</p>`,28)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};